
-- ── blog_posts ──────────────────────────────────────
on conflict (slug) do update set title = excluded.title, bucket = excluded.bucket, hero_image = excluded.hero_image, blurb = excluded.blurb, paragraphs = excluded.paragraphs, published = excluded.published, sort_order = excluded.sort_order;

-- ── stockists ───────────────────────────────────────
delete from public.stockists;
